
from pathlib import Path
def render(cfg):
    transport=f"serial: {cfg.serial_port}" if cfg.connection=="usb" else f"cni: {cfg.cni_host}:{cfg.cni_port}"
    return f"mqtt:\n  host: {cfg.mqtt.host}\n  port: {cfg.mqtt.port}\ndiscovery: {str(cfg.discovery).lower()}\n{transport}\n"
def write(cfg):
    p=Path("/config/cmqttd/cmqttd.yaml"); p.parent.mkdir(parents=True,exist_ok=True); p.write_text(render(cfg))
